// === Tab: mySketch ===
const sketch = (p) => {
  let min_width;

  let patterns = [];

  p.setup = () => {
    p.randomSeed(p.random() * 998244353);
    p.noiseSeed(p.random() * 998244353);

    p.createCanvas(p.windowWidth, p.windowHeight);
    min_width = p.min(p.width, p.height);

    p.background(0);

    let cell_w = min_width * 0.95 / 5;
    patterns.push(
      new Pattern(
        p.width / 2 + cell_w,
        p.height / 2 + cell_w,
        cell_w,
        p.int(p.random(8, 21)),
        p.int(p.random(2))
      )
    ); //只生成一个
  };

  p.draw = () => {
    for (let i = 0; i < patterns.length; ++i) {
      patterns[i].display(p.frameCount);
    }
  };

  class Pattern {
    pos;
    width;
    nline;
    sel;
    ir;
    or;
    iv;
    ov;
    ofa;
    time;
    mxtime;

    background_color;
    a;
    b;
    c;
    d;
    alpha;
    cx;
    cy;

    colorTimer;
    colorInterval;
    currentColorIndex;
    colors;

    constructor(x, y, width, nline, sel) {
      this.pos = p.createVector(0.75 * x, 0.75 * y); //位置
      this.width = width * 5; //把方形放大
      this.nline = nline;
      this.sel = sel;

      this.time = 0;

      this.mxtime = p.int(p.random(10, 17)) * 100;
      this.alpha = 20 / nline * 3;

      this.cx = p.random();
      this.cy = p.random();

      this.background_color = p.color(p.random(30));

      this.ir = [];
      this.or = [];

      this.iv = [];
      this.ov = [];

      this.ofa = [];

      this.a = [];
      this.b = [];
      this.c = [];
      this.d = [];
      for (let i = 0; i < nline; ++i) {
        let tr = p.random(0.4, 0.6);
        this.ir.push(tr);
        this.or.push(p.min(0.95, tr + p.random(0.1, 0.3)));

        this.ofa.push(i * p.PI * 0.25);

        this.iv.push(p.random(0.001, 0.003));
        this.ov.push(p.random(0.001, 0.003));

        this.a.push(p.random(0.1, 0.5));
        this.b.push(p.random(0.1, 0.5));
        this.c.push(p.int(p.random(1, 4)));
        this.d.push(p.random());
      }
      p.push();
      p.blendMode(p.BLEND);
      p.rectMode(p.CENTER);
      p.translate(this.pos);
      p.noStroke();
      p.fill(this.background_color);
      p.rect(0, 0, this.width);
      p.pop();

      this.colorTimer = 0;
      this.colorInterval = 300; // 颜色变化的时间间隔（帧）
      this.currentColorIndex = 0;
      this.colors = ["red", "green", "blue"]; // 三种颜色中选
    }

    display(t) {
      p.push();
      p.blendMode(p.BLEND);
      p.rectMode(p.CENTER);
      p.translate(this.pos);

      p.blendMode(p.ADD);
      p.noFill();

      p.strokeWeight(this.width / 300); //修改线条粗细
      for (let i = 0; i < this.nline; ++i) {
        let colorIndex = (this.currentColorIndex + p.floor(i / 3)) % this.colors.length;
        let selectedColor = this.colors[colorIndex];
        p.stroke(
          getColorValue(selectedColor, "red"),
          getColorValue(selectedColor, "green"),
          getColorValue(selectedColor, "blue"),
          this.alpha
        );
        if (t < this.mxtime) {
          //for(let t=0;t<this.mxtime;++t){//noloop ver.
          let a1 = t * this.iv[i] * p.TWO_PI + this.ofa[i];
          let a2 = t * this.ov[i] * p.TWO_PI + this.ofa[i];
          let x1 = this.ir[i] * p.cos(a1);
          let y1 = this.ir[i] * p.sin(a1);
          let x2 = this.or[i] * p.cos(a2);
          let y2 = this.or[i] * p.sin(a2);

          p.push();
          p.rect(
            x1 * this.width * 0.5,
            y1 * this.width * 0.5,
            (x2 - x1) * this.width * 0.5,
            (y2 - y1) * this.width * 0.5
          );
          p.pop();
        }
      }
      p.pop();
      this.colorTimer++;
      if (this.colorTimer >= this.colorInterval) {
        this.currentColorIndex++;
        this.colorTimer = 0;
      }
    }
  }

  function getColorValue(color, channel) {
    if (color === "red") {
      if (channel === "red") return 255;
      else return 0;
    } else if (color === "green") {
      if (channel === "green") return 255;
      else return 0;
    } else if (color === "blue") {
      if (channel === "blue") return 255;
      else return 0;
    }
  }
};

new p5(sketch);

